#include <stdio.h>
 #include <stdlib.h>
 #include <stdbool.h>

 typedef struct node
 {
  int data;
  struct node* next;
  struct node* prev;
 } node;

 node* top = NULL;

 void pushhead(int value)
 {
  node* new_node = (node*)malloc(sizeof(node));

  new_node->data = value;
  new_node->next = top;
  new_node->prev = NULL;

  if (top != NULL)
  {
  top->prev = new_node;
  }

  top = new_node;
 }

 void pushtail(int value)
 {
  node* new_node = (node*)malloc(sizeof(node));
  new_node->data = value;
  new_node->next = NULL;
  new_node->prev = NULL;

  if (top == NULL)
  {
  top = new_node;
  return;
  }

  node* temp = top;
  while (temp->next != NULL)
  {
  temp = temp->next;
  }

  temp->next = new_node;
  new_node->prev = temp;
 }

 int pophead()
 {
  int value = top->data;
  node* temp = top;
  top = top->next;

  if (top != NULL)
  {
  top->prev = NULL;
  }

  free(temp);
  return value;
 }

