 using namespace std;

 struct Node {
  char data;
  Node* next;
 };


 void push(Node*& top, char value) {
  Node* newnode = new Node{value, top};
  top = newnode;
 }


 char pop(Node*& top) {
  if (top = nullptr) return '\0';
  char value = top->data;
  Node* temp = top;
  top = top->next;
  delete temp;
  return value;
 }


 bool palindrome(string s) {
  Node* top = nullptr;


  for (char c : s) {
  push(top, c);
  }


  for (char c : s) {
  char popped = pop(top);
  if (c != popped) return false;
  }

  return true;
 }

