#include <stdio.h>
int main() {
    int n, i, x, first = -2000000, second = -2000000;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        if (x > first) {
            second = first;
            first = x;
        } else if (x > second) {
            second = x;
        }
    }
    if (second == -2000000) printf("NONE\n");
    else printf("%d\n", second);
    return 0;
}

#include <stdio.h>
int main() {
    int n, i, x, first = -2000000, second = -2000000;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        if (x > first) {
            second = first;
            first = x;
        } else if (x > second && x < first) {
            second = x;
        }
    }
    if (second == -2000000) printf("NO\n");
    else printf("%d\n", second);
    return 0;
}

