using namespace std;
int main() {
    int n, t;
    cin >> n;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cin >> t;
    int pos = -1;
    for (int i = n - 1; i >= 0; i--) {
        if (v[i] == t) {
            pos = i + 1;
            break;
        }
